/* Enforce hidden attribute precedence */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1a1c23;
  --color-meter-body: #475569;
  --color-meter-dark: #334155;
  --color-meter-border: #0f172a;
  --color-screen-bg: #102a27;
  --color-screen-glow: #38bdf8;
  --color-screen-text: #67e8f9;
  --color-expired-bg: #7f1d1d;
  --color-expired-glow: #ef4444;
  --color-expired-text: #fecaca;
  --color-btn-face: #e2e8f0;
  --color-btn-border: #94a3b8;
  --color-btn-shadow: #64748b;
  --color-btn-active: #cbd5e1;
  --color-reset-face: #f87171;
  --color-reset-shadow: #b91c1c;
  --font-stack: "Courier New", Courier, monospace, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  background-image: 
    radial-gradient(#2e3440 10%, transparent 11%),
    radial-gradient(#2e3440 10%, transparent 11%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  font-family: var(--font-stack);
  font-size: 16px;
  color: #f8fafc;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 24px 16px;
}

.meter-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  max-width: 380px;
}

/* Top Cap & Dome */
.meter-cap {
  width: 160px;
  height: 24px;
  background: var(--color-meter-dark);
  border: 4px solid var(--color-meter-border);
  border-bottom: none;
  box-shadow: inset 0 4px 0 #64748b;
  display: flex;
  justify-content: center;
  align-items: center;
}

.meter-light-housing {
  width: 24px;
  height: 12px;
  background: #000;
  border: 2px solid var(--color-meter-border);
  display: flex;
  justify-content: center;
  align-items: center;
}

.meter-light {
  width: 16px;
  height: 6px;
  background: #4ade80;
  box-shadow: 0 0 6px #4ade80;
  transition: background 0.2s, box-shadow 0.2s;
}

.meter-light.expired {
  background: #ef4444;
  box-shadow: 0 0 8px #ef4444;
}

/* Main Meter Housing */
.meter-head {
  width: 100%;
  background: var(--color-meter-body);
  border: 4px solid var(--color-meter-border);
  box-shadow:
    inset 4px 4px 0 #94a3b8,
    inset -4px -4px 0 #1e293b,
    8px 8px 0 rgba(0, 0, 0, 0.4);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.meter-visor {
  background: #090d16;
  padding: 12px;
  border: 4px solid var(--color-meter-border);
  box-shadow: inset 2px 2px 0 #000;
}

.meter-screen {
  position: relative;
  background-color: var(--color-screen-bg);
  border: 4px solid #042f2e;
  padding: 18px 12px;
  text-align: center;
  box-shadow: inset 0 0 12px rgba(0, 0, 0, 0.8);
  transition: background-color 0.2s ease, border-color 0.2s ease;
}

.meter-screen.expired {
  background-color: var(--color-expired-bg);
  border-color: #450a0a;
}

.screen-scanlines {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.15),
    rgba(0, 0, 0, 0.15) 2px,
    transparent 2px,
    transparent 4px
  );
  pointer-events: none;
}

.screen-subhead {
  font-size: 0.75rem;
  letter-spacing: 2px;
  font-weight: bold;
  color: #a5f3fc;
  margin-bottom: 6px;
  text-shadow: 1px 1px 0 #000;
}

.meter-screen.expired .screen-subhead {
  color: #fca5a5;
}

.time-digits {
  font-size: 2.25rem;
  font-weight: 900;
  letter-spacing: 3px;
  color: var(--color-screen-text);
  text-shadow: 0 0 6px var(--color-screen-glow), 2px 2px 0 #000;
}

.meter-screen.expired .time-digits {
  color: var(--color-expired-text);
  text-shadow: 0 0 8px var(--color-expired-glow), 2px 2px 0 #000;
}

.status-banner {
  margin-top: 10px;
  font-size: 1.25rem;
  font-weight: 900;
  letter-spacing: 4px;
  color: #ffffff;
  background-color: #dc2626;
  padding: 4px 8px;
  border: 2px solid #fee2e2;
  box-shadow: 0 0 10px #ef4444;
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  0% { transform: scale(0.98); opacity: 0.85; }
  100% { transform: scale(1.02); opacity: 1; }
}

/* Coin Slot Accent */
.coin-slot {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.slot-opening {
  width: 70px;
  height: 8px;
  background-color: #0b0f19;
  border: 2px solid #000;
  box-shadow: 0 2px 0 #64748b;
}

.slot-label {
  font-size: 0.75rem;
  letter-spacing: 1.5px;
  font-weight: 700;
  color: #94a3b8;
}

/* Controls & Buttons */
.controls {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pixel-btn {
  appearance: none;
  border: 3px solid var(--color-meter-border);
  background: var(--color-btn-face);
  color: #0f172a;
  font-family: inherit;
  font-size: 1rem;
  font-weight: 900;
  padding: 12px 16px;
  cursor: pointer;
  box-shadow:
    inset -3px -3px 0 var(--color-btn-shadow),
    inset 3px 3px 0 #ffffff,
    4px 4px 0 #000;
  transform: translate(0, 0);
  transition: transform 0.05s, box-shadow 0.05s;
}

.pixel-btn:hover {
  background: #f1f5f9;
}

.pixel-btn:focus-visible {
  outline: 3px dashed #38bdf8;
  outline-offset: 3px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow:
    inset -2px -2px 0 var(--color-btn-shadow),
    inset 2px 2px 0 #ffffff,
    2px 2px 0 #000;
}

.reset-btn {
  background: var(--color-reset-face);
  color: #ffffff;
  box-shadow:
    inset -3px -3px 0 var(--color-reset-shadow),
    inset 3px 3px 0 #fca5a5,
    4px 4px 0 #000;
  margin-top: 4px;
}

.reset-btn:hover {
  background: #ef4444;
}

.reset-btn:active {
  transform: translate(2px, 2px);
  box-shadow:
    inset -2px -2px 0 var(--color-reset-shadow),
    inset 2px 2px 0 #fca5a5,
    2px 2px 0 #000;
}

/* Pole and Base */
.meter-pole {
  width: 44px;
  height: 48px;
  background: repeating-linear-gradient(
    90deg,
    #334155,
    #334155 10px,
    #475569 10px,
    #475569 20px
  );
  border: 4px solid var(--color-meter-border);
  border-top: none;
  border-bottom: none;
}

.meter-base {
  width: 120px;
  height: 16px;
  background: #1e293b;
  border: 4px solid var(--color-meter-border);
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4);
}

document.addEventListener('DOMContentLoaded', () => {
  let remainingSeconds = 0;
  let timerInterval = null;

  const timeDisplay = document.getElementById('time-display');
  const meterScreen = document.getElementById('meter-screen');
  const statusMessage = document.getElementById('status-message');
  const statusIndicator = document.getElementById('status-indicator');
  const btnAdd15 = document.getElementById('btn-add-15');
  const btnAdd60 = document.getElementById('btn-add-60');
  const btnReset = document.getElementById('btn-reset');

  function formatTime(totalSeconds) {
    const safeSeconds = Math.max(0, totalSeconds);
    const hours = Math.floor(safeSeconds / 3600);
    const minutes = Math.floor((safeSeconds % 3600) / 60);
    const seconds = safeSeconds % 60;

    const formattedMinutes = String(minutes).padStart(2, '0');
    const formattedSeconds = String(seconds).padStart(2, '0');

    return `${hours}:${formattedMinutes}:${formattedSeconds}`;
  }

  function updateUI() {
    timeDisplay.textContent = formatTime(remainingSeconds);

    if (remainingSeconds <= 0) {
      meterScreen.classList.add('expired');
      statusIndicator.classList.add('expired');
      statusMessage.removeAttribute('hidden');
    } else {
      meterScreen.classList.remove('expired');
      statusIndicator.classList.remove('expired');
      statusMessage.setAttribute('hidden', '');
    }
  }

  function tick() {
    if (remainingSeconds > 0) {
      remainingSeconds -= 1;
      if (remainingSeconds === 0) {
        clearInterval(timerInterval);
        timerInterval = null;
      }
      updateUI();
    }
  }

  function startTimer() {
    if (!timerInterval && remainingSeconds > 0) {
      timerInterval = setInterval(tick, 1000);
    }
  }

  function addTime(secondsToAdd) {
    remainingSeconds += secondsToAdd;
    updateUI();
    startTimer();
  }

  function resetMeter() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    remainingSeconds = 0;
    updateUI();
  }

  btnAdd15.addEventListener('click', () => {
    addTime(15 * 60);
  });

  btnAdd60.addEventListener('click', () => {
    addTime(60 * 60);
  });

  btnReset.addEventListener('click', () => {
    resetMeter();
  });

  // Initial render (starts at 0, expired screen)
  updateUI();
});
